// Article 50 does not treat every file the same, so the first job is to say
// what kind of output this is. The mime type decides it, with the extension
// as a fallback for the files Drive reports as octet-stream.
const settings = $('Read Disclosure Settings').first().json;
const file = $('New File In The Review Folder').first().json;

const name = String(file.name || 'untitled');
const mime = String(file.mimeType || '').toLowerCase();
const ext = (name.split('.').pop() || '').toLowerCase();

function kindOf() {
  if (mime.startsWith('image/')) return 'image';
  if (mime.startsWith('video/')) return 'video';
  if (mime.startsWith('audio/')) return 'audio';
  if (mime.startsWith('text/') || mime.indexOf('document') !== -1 || mime.indexOf('markdown') !== -1) return 'text';
  if (['png', 'jpg', 'jpeg', 'webp', 'gif', 'svg'].indexOf(ext) !== -1) return 'image';
  if (['mp4', 'mov', 'webm', 'mkv'].indexOf(ext) !== -1) return 'video';
  if (['mp3', 'wav', 'm4a', 'ogg'].indexOf(ext) !== -1) return 'audio';
  if (['txt', 'md', 'html', 'docx'].indexOf(ext) !== -1) return 'text';
  return 'other';
}

const stamp = new Date();

return [{
  json: {
    registerId: 'DISC-' + stamp.toISOString().slice(0, 10).replace(/-/g, '') + '-' + String(file.id || '').slice(-6),
    detectedAt: stamp.toISOString(),
    fileId: file.id || '',
    fileName: name,
    mimeType: mime || 'unknown',
    sizeBytes: Number(file.size || 0),
    assetKind: kindOf(),
    contentSha256: String($json.contentSha256 || ''),
    organisation: String(settings['Organisation'] || '').trim(),
    role: String(settings['Role'] || 'deployer').trim().toLowerCase(),
    publishesPublicInterest: String(settings['Publishes Public Interest Content'] || 'no').trim().toLowerCase() === 'yes',
    labelTemplate: String(settings['Label Wording'] || 'This {kind} was generated using artificial intelligence by {organisation}.'),
    reviewerEmail: String(settings['Reviewer Email'] || '').trim(),
    toolUsed: String(settings['Generation Tool'] || 'an AI system').trim(),
  },
}];

// Which part of Article 50 bites depends on the output and on who you are in
// the chain. What a workflow can decide on its own is separated here from
// what genuinely needs a person to look, and only the second kind is held
// back for sign-off.
const a = $json;

const SYNTHETIC = ['image', 'video', 'audio'];
const duties = [];
let needsSignOff = false;
let signOffReason = '';

if (SYNTHETIC.indexOf(a.assetKind) !== -1) {
  // Providers of generative systems must mark synthetic output in a
  // machine-readable way. That part is mechanical.
  duties.push('Article 50(2) machine-readable marking of synthetic content');

  // Whether the same file is also a deepfake of a real person is a judgement
  // about the content, not something a mime type can answer.
  duties.push('Article 50(4) deepfake disclosure, to be confirmed');
  needsSignOff = true;
  signOffReason = 'Confirm whether this ' + a.assetKind + ' depicts a real, identifiable person or event. If it does, the deepfake disclosure must be visible on publication.';
} else if (a.assetKind === 'text') {
  duties.push('Article 50(2) machine-readable marking of synthetic content');
  if (a.publishesPublicInterest) {
    duties.push('Article 50(4) disclosure for AI-generated text published to inform the public');
    needsSignOff = true;
    signOffReason = 'Confirm whether this text is published to inform the public on a matter of public interest. If it is, the disclosure must appear with the published text.';
  }
} else {
  duties.push('No Article 50 output duty identified for this file type. Logged for completeness.');
}

const visibleLabel = a.labelTemplate
  .replace(/\{kind\}/g, a.assetKind)
  .replace(/\{organisation\}/g, a.organisation || 'this organisation')
  .replace(/\{tool\}/g, a.toolUsed);

// A lightweight, readable record of the declaration. It is not a signed C2PA
// manifest and does not claim to be one, but it travels with the file and is
// machine-readable, which is what the register needs to point at.
const manifest = {
  disclosure: {
    framework: 'EU AI Act Article 50',
    dutiesIdentified: duties,
    declaredBy: a.organisation,
    roleInChain: a.role,
    generatedWith: a.toolUsed,
    syntheticContent: true,
    visibleLabel: visibleLabel,
    asset: {
      fileName: a.fileName,
      mimeType: a.mimeType,
      sizeBytes: a.sizeBytes,
      sha256: a.contentSha256,
    },
    jsonLd: {
      '@context': 'https://schema.org',
      '@type': 'CreativeWork',
      name: a.fileName,
      creativeWorkStatus: 'AI-generated',
      disambiguatingDescription: visibleLabel,
      creator: { '@type': 'SoftwareApplication', name: a.toolUsed },
      publisher: { '@type': 'Organization', name: a.organisation },
      sha256: a.contentSha256,
    },
    registerId: a.registerId,
    declaredAt: new Date().toISOString(),
  },
};

return [{
  json: Object.assign({}, a, {
    duties: duties.join(' | '),
    visibleLabel: visibleLabel,
    needsSignOff: needsSignOff,
    signOffReason: signOffReason,
    status: needsSignOff ? 'Awaiting sign off' : 'Disclosed',
    manifestFileName: a.registerId + '-disclosure.json',
    manifest: manifest,
  }),
}];

// Pick up only the rows a reviewer has signed off since the last sweep, so a
// file is never moved twice and a row that is still waiting is left alone.
const rows = $input.all().map(function (i) { return i.json; });

const ready = rows.filter(function (r) {
  const status = String(r['Status'] || '').trim().toLowerCase();
  const moved = String(r['Moved'] || 'no').trim().toLowerCase();
  return status === 'signed off' && moved !== 'yes' && String(r['File ID'] || '').trim() !== '';
});

if (!ready.length) return [];

return ready.map(function (r) {
  return {
    json: {
      registerId: r['Register ID'],
      fileId: String(r['File ID']).trim(),
      fileName: r['File Name'],
      signedOffBy: r['Signed Off By'] || '',
      publishedAt: new Date().toISOString(),
    },
  };
});
